import {attachCardDrag} from '../shared/drag.js';
import {mountExperiment} from '../model-kit/session.js';
import {definition} from '../../../embed/definitions/lab-authority.js';
import {e} from '../../../embed/definitions/_lab.js';
import {roles,methods,scenarios,project,compare,summary,describe,loadScenario,arrange} from './model.js';
import {renderArticle} from './view.js';

const options=(values,current)=>values.map((name,i)=>`<option value="${i}" ${i===current?'selected':''}>${e(name)}</option>`).join('');
const select=(key,index,value,values,label)=>`<label for="authority-${key}-${index}">${e(label)}<select id="authority-${key}-${index}" data-field="${key}" data-index="${index}">${options(values,value)}</select></label>`;
const numeric=(key,value,label,min,max,index='')=>`<label for="authority-${key}-${index}">${e(label)}<input id="authority-${key}-${index}" type="number" min="${min}" max="${max}" step="1" value="${value}" data-field="${key}" ${index!==''?`data-index="${index}"`:''}></label>`;
function render(state,{pinned}){
 const r=project(state),c=compare(state,pinned);
 const kinds={knowledge:'Knows local need',deciders:'Can decide',consequences:'Bears consequences'};
 return `<div class="experiment-toolbar"><label for="authority-scenario">Situation<select id="authority-scenario">${Object.entries(scenarios).map(([id,s])=>`<option value="${id}" ${state.scenario===id?'selected':''}>${e(s.label)}</option>`).join('')}</select></label><button data-arrange="local">Local authority</button><button data-arrange="central">Central authority</button><button data-arrange="context">Local + shared context</button></div>
 <p class="authority-intro">${e(scenarios[state.scenario].description)} Move a card to change its owner, or use its menu.</p>
 <section class="authority-board experiment-board" aria-label="Knowledge, authority and consequences by role">${roles.map((role,i)=>`<section class="authority-role" data-role="${i}" data-drop-id="${i}" aria-label="${e(role)}"><h2>${e(role)}</h2>${numeric('capacity',state.capacity[i],'Concurrent decisions',1,3,i)}<div class="authority-cards">${Object.entries(kinds).flatMap(([key,label])=>state[key].map((owner,team)=>owner===i?`<div class="authority-card authority-${key}" data-drag-id="${key}:${team}" data-card="${key}:${team}"><span class="authority-kind">${e(label)}</span><strong data-drag-handle title="Drag to move; the menu provides the keyboard alternative">${e(roles[team])}</strong>${select(key,team,owner,roles,`Move ${label.toLowerCase()} for ${roles[team]}`)}</div>`:'')).join('')}</div></section>`).join('')}</section>
 <div class="authority-consult">${roles.slice(0,2).map((role,i)=>`<fieldset><legend>${e(role)} decisions</legend>${[['consultLocal','Ask the local-need holder'],['consultLink','Ask for shared context'],['approval','Require desk permission']].map(([key,label])=>`<label class="authority-check"><input type="checkbox" id="authority-${key}-${i}" data-field="${key}" data-index="${i}" ${state[key][i]?'checked':''}>${label}</label>`).join('')}</fieldset>`).join('')}<div>${select('linkKnowledge','',state.linkKnowledge,roles,'Shared context held by')}<p>Consultation supplies facts. Permission only adds a desk queue.</p></div></div>
 <section class="experiment-output" aria-label="Decision results"><div class="authority-metrics"><p><strong>${r.onTime}/${r.total}</strong>on time</p><p><strong>${r.localFit}/${r.total}</strong>fit local needs</p><p><strong>${state.coupled?`${r.compatible}/${state.demand}`:'—'}</strong>${state.coupled?'pairs connect':'independent requests'}</p><p><strong>${r.finish}</strong>last finish tick</p></div><p class="authority-verdict">${e(summary(state,r))}</p>${c?`<div class="authority-comparison"><h3>Pinned arrangement · same situation</h3><p>${e(summary(state,c.result))}</p><p>Replays pinned authority, information locations, consultation, permission and capacity on current requests, timing and needs.${c.situationChanged?' Situation assumptions have changed since pinning.':''}</p></div>`:''}
 <p class="authority-pan">Scroll across the queue diagram to read every decision →</p><div class="authority-queue">${renderArticle(state,{width:850,colors:Object.fromEntries(['ink','paper','accent','muted','line'].map(k=>[k,`var(--${k})`]))}).svg}</div></section>
 <details id="authority-trace"><summary>Trace each decision and its consequences</summary><div class="authority-traces">${r.decisions.map(d=>`<article><h3>${d.id} · ${methods[d.method]}</h3><p>${e(d.reason)} ${d.knowsLocal?'Local need available.':'Local need missing.'} ${d.knowsLink?'Shared context available.':'Shared context missing.'}</p><ol><li>All requests arrive at tick 0; information ready at ${d.ready}.</li>${d.steps.map(s=>`<li>${e(roles[s.role])}: ${s.kind} ${s.start}–${s.end}; waited ${s.wait} ticks.</li>`).join('')}</ol><p>${d.localFit?'Fits':'Does not fit'} local need. ${state.coupled?(d.compatible?'Pair connects.':'Pair does not connect.'):'No shared dependency.'} ${d.onTime?'Within':'Past'} deadline. Consequences go to ${e(roles[d.consequence])}.</p></article>`).join('')}</div><h3>Who carries the effects?</h3>${r.burdens.map(b=>`<p><strong>${e(b.role)}</strong>: ${b.late} late, ${b.misfit} local mismatches, ${b.disconnected} disconnected decisions. These counts can overlap.</p>`).join('')}</details>
 <details id="authority-assumptions"><summary>Edit the situation and timing assumptions</summary><div class="authority-assumptions">${numeric('demand',state.demand,'Requests per team',1,6)}${numeric('deadline',state.deadline,'Deadline tick',1,30)}${numeric('duration',state.duration,'Decision duration',1,4)}${numeric('consultationDelay',state.consultationDelay,'Consultation delay',0,4)}${numeric('approvalDuration',state.approvalDuration,'Permission duration',1,4)}${select('fallback','',state.fallback,methods,'Method with missing information')}${select('sharedMethod','',state.sharedMethod,methods,'Agreed connection method')}${state.needs.map((v,i)=>select('needs',i,v,methods,`${roles[i]} needs`)).join('')}<label class="authority-check"><input id="authority-coupled" type="checkbox" data-field="coupled" ${state.coupled?'checked':''}>Pairs must use the same method</label></div></details>
 <details id="authority-mechanism"><summary>How this model works · limits and source</summary><p>Each pair contains one request per team; every request arrives at tick 0. Accurate consultation completes after the stated delay, with parallel requests and no consultation capacity limit. Decisions then share each role’s finite slots in arrival order, with Harbour first when tied. A required permission uses the same desk slots after the local decision.</p><p>The rule uses the agreed connection method when shared context is known and coupling applies; otherwise it uses a known local need, then the fallback. Shared context can improve compatibility while sacrificing local fit. Permission does not change the choice. Moving consequences changes who bears them, never the decision rule. No negotiation, adaptation, trust, or empirical staffing prediction is modelled.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-422-exception-presence-delegation" target="_blank" rel="noopener">Exception, Presence, Delegation</a>. The queue mechanism and fictional examples are this tool’s own assumptions.</p></details>`;
}
function bind({root,state,change,report}){
 root.querySelector('#authority-scenario').addEventListener('change',event=>change(loadScenario(state,event.target.value),'Situation changed; arrangement retained.'));
 root.querySelectorAll('[data-arrange]').forEach(button=>button.addEventListener('click',()=>change(arrange(state,button.dataset.arrange),'Arrangement changed.')));
 root.querySelectorAll('[data-field]').forEach(input=>input.addEventListener('change',()=>{const next=structuredClone(state),value=input.type==='checkbox'?input.checked:Number(input.value),{field,index}=input.dataset;if(index!==undefined&&index!=='')next[field][Number(index)]=value;else next[field]=value;change(next,'Assignment or assumption changed.');}));
 // Shared pointer handles preserve native select gestures and support touch/edge scrolling.
 return attachCardDrag({root,onDrop:({itemId,dropId})=>{const [key,team]=itemId.split(':'),next=structuredClone(state);next[key][Number(team)]=Number(dropId);change(next,'Card moved.');}});
}
await mountExperiment({route:'authority',definition,render,bind,describe});
